// Service orchestrates worktree operations over a Git backend and a Prompter.
// out receives user-facing diagnostics (typically stderr).
type Service struct {
	git    Git
	prompt Prompter
	out    io.Writer
}

// NewService returns a Service backed by the given Git, Prompter, and
// diagnostics writer.
func NewService(git Git, prompt Prompter, out io.Writer) *Service {
