// CreateOptions selects how a worktree should be created.
type CreateOptions struct {
	Branch         string
	ExistingBranch bool
}

// Create makes a new worktree at <main-root>/.worktrees/<sanitized-branch>,
// copies configured files in, optionally trusts mise, and creates a tmp/ dir.
// It returns the absolute worktree path.
func (s *Service) Create(ctx context.Context, opts CreateOptions) (string, error) {
	root, err := s.git.MainRoot(ctx)
	if err != nil {
		return "", err
	}
	path := filepath.Join(root, worktreesDir, worktreeDirName(opts.Branch))
	switch _, err := os.Stat(path); {
	case err == nil:
		return "", fmt.Errorf("worktree already exists at %s", path)
	case !errors.Is(err, fs.ErrNotExist):
		return "", fmt.Errorf("check worktree path %s: %w", path, err)
	}
