	if err != nil {
		return "", err
	}
	if opts.ExistingBranch {
		if err := s.addExistingBranchWorktree(ctx, root, path, opts.Branch); err != nil {
			return "", err
		}
	} else {
		if err := s.git.FetchOriginBranch(ctx, root, "main"); err != nil {
			return "", err
		}
		if err := s.git.AddWorktree(ctx, root, path, opts.Branch, mainStartPoint); err != nil {
			return "", err
		}
	}
	s.copyFiles(root, path, files)
	if s.git.MiseTrusted(ctx, root) {
		if err := s.git.MiseTrust(ctx, path); err != nil {
			_, _ = fmt.Fprintf(s.out, "warning: mise trust failed: %v\n", err)
		}
	}
	if err := os.MkdirAll(filepath.Join(path, "tmp"), 0o750); err != nil {
		return "", fmt.Errorf("create tmp dir: %w", err)
	}
	return path, nil
}

func worktreeDirName(branch string) string {
	return strings.ReplaceAll(branch, "/", "-")
}

func (s *Service) addExistingBranchWorktree(ctx context.Context, root, path, branch string) error {
	exists, err := s.git.LocalBranchExists(ctx, root, branch)
	if err != nil {
		return err
	}
	if exists {
		return s.git.AddWorktreeForBranch(ctx, root, path, branch)
	}
	if err := s.git.FetchOriginBranch(ctx, root, branch); err != nil {
		return err
	}
	exists, err = s.git.OriginBranchExists(ctx, root, branch)
	if err != nil {
		return err
	}
	if !exists {
		return fmt.Errorf("no local or origin branch found for %q", branch)
	}
	return s.git.AddWorktreeTrackingBranch(ctx, root, path, branch, originBranch(branch))
}

func originBranch(branch string) string {
	return "origin/" + branch
}

func (s *Service) includedFiles(ctx context.Context, root string, patterns []string) ([]string, error) {
	if len(patterns) == 0 {
		return nil, nil
	}
	ignoredFiles, err := s.git.ListIgnoredFiles(ctx, root)
	if err != nil {
		return nil, err
	}
	return matchIncludePatterns(patterns, ignoredFiles), nil
}

func matchIncludePatterns(patterns, files []string) []string {
	ps := make([]gitignore.Pattern, 0, len(patterns))
	for _, pattern := range patterns {
		ps = append(ps, gitignore.ParsePattern(pattern, nil))
	}
	matcher := gitignore.NewMatcher(ps)
	included := make([]string, 0, len(files))
	for _, file := range files {
		rel, ok := cleanRelativeFile(file)
		if !ok || isWorktreeFile(rel) || !matcher.Match(splitRelativePath(rel), false) {
			continue
		}
		included = append(included, rel)
	}
	return included
}

func isWorktreeFile(rel string) bool {
	slash := filepath.ToSlash(rel)
	return slash == worktreesDir || strings.HasPrefix(slash, worktreesDir+"/")
}

func cleanRelativeFile(rel string) (string, bool) {
	if rel == "" || filepath.IsAbs(rel) {
		return "", false
	}
	clean := filepath.Clean(filepath.FromSlash(rel))
	if clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", false
	}
	return clean, true
}

func splitRelativePath(rel string) []string {
	return strings.Split(filepath.ToSlash(rel), "/")
}

func (s *Service) copyFiles(root, dest string, files []string) {
	for _, rel := range files {
		if err := copyFile(filepath.Join(root, rel), filepath.Join(dest, rel)); err != nil {
			_, _ = fmt.Fprintf(s.out, "warning: skipped %s: %v\n", rel, err)
		}
	}
}

func copyFile(src, dst string) error {
	srcInfo, err := os.Lstat(src)
	if err != nil {
		return err
	}
	if !srcInfo.Mode().IsRegular() {
		return fmt.Errorf("source is not a regular file")
	}
	in, err := os.Open(src) //nolint:gosec // src derived from repo root + config
	if err != nil {
		return err
	}
	defer in.Close() //nolint:errcheck // read-only; close error not actionable
	openedInfo, err := in.Stat()
	if err != nil {
		return err
	}
	if !openedInfo.Mode().IsRegular() || !os.SameFile(srcInfo, openedInfo) {
		return fmt.Errorf("source changed while opening")
	}
	if err := os.MkdirAll(filepath.Dir(dst), 0o750); err != nil {
		return err
	}
	out, err := os.OpenFile(dst, os.O_WRONLY|os.O_CREATE|os.O_EXCL, srcInfo.Mode().Perm()) //nolint:gosec // dst is inside the new worktree
	if err != nil {
		return err
	}
	if _, err := io.Copy(out, in); err != nil {
		_ = out.Close()
		_ = os.Remove(dst)
		return err
	}
	if err := out.Close(); err != nil {
		_ = os.Remove(dst)
		return err
	}
	if err := os.Chmod(dst, srcInfo.Mode().Perm()); err != nil {
		_ = os.Remove(dst)
		return err
	}
	return nil
}

// RemoveOptions selects which worktrees to remove and how.
type RemoveOptions struct {
	Name  string
	All   bool
	Yes   bool
	Force bool
}

// Remove deletes worktrees chosen by name, by --all, or interactively. Dirty
// worktrees are refused unless Force is set. A confirmation prompt runs unless
// Yes is set.
func (s *Service) Remove(ctx context.Context, opts RemoveOptions) error {
	root, err := s.git.MainRoot(ctx)
	if err != nil {
		return err
	}
	wts, err := s.git.ListWorktrees(ctx, root)
	if err != nil {
		return err
	}
	targets, err := s.selectTargets(nonMain(wts), opts)
	if err != nil {
		return err
	}
	if len(targets) == 0 {
		_, _ = fmt.Fprintln(s.out, "No worktrees to remove.")
		return nil
	}
	if !opts.Yes {
		ok, err := s.prompt.Confirm(confirmMessage(targets))
		if err != nil {
			return err
		}
		if !ok {
			_, _ = fmt.Fprintln(s.out, "Aborted.")
			return nil
		}
	}
	return s.removeAll(ctx, root, targets, opts.Force)
}

func (s *Service) selectTargets(candidates []Worktree, opts RemoveOptions) ([]Worktree, error) {
	switch {
	case opts.All:
		return candidates, nil
	case opts.Name != "":
		target, err := filepath.Abs(opts.Name)
		if err != nil {
			return nil, fmt.Errorf("resolve %q: %w", opts.Name, err)
		}
		var matches []Worktree
		for _, w := range candidates {
			if matchesRemoveTarget(w, opts.Name, target) {
				matches = append(matches, w)
			}
		}
		switch len(matches) {
		case 0:
			return nil, fmt.Errorf("no worktree found matching %q", opts.Name)
		case 1:
			return matches, nil
		default:
			return nil, fmt.Errorf("multiple worktrees found matching %q", opts.Name)
		}
	default:
		return s.prompt.Select(candidates)
	}
}

func matchesRemoveTarget(w Worktree, name, absPath string) bool {
	return filepath.Base(w.Path) == name || w.Path == absPath || w.Branch == name
}

func (s *Service) removeAll(ctx context.Context, root string, targets []Worktree, force bool) error {
	failed := false
	for _, w := range targets {
		if !force {
			dirty, err := s.git.IsDirty(ctx, w.Path)
			if err != nil {
				_, _ = fmt.Fprintf(s.out, "skip %s: %v\n", w.Path, err)
				failed = true
				continue
			}
			if dirty {
				_, _ = fmt.Fprintf(s.out, "skip %s: has uncommitted changes (use --force)\n", w.Path)
				failed = true
				continue
			}
		}
		if err := s.git.RemoveWorktree(ctx, root, w.Path, force); err != nil {
			_, _ = fmt.Fprintf(s.out, "failed to remove %s: %v\n", w.Path, err)
			failed = true
			continue
		}
		_, _ = fmt.Fprintf(s.out, "removed %s\n", w.Path)
	}
	if failed {
		return errors.New("one or more worktrees could not be removed")
	}
	return nil
}

func nonMain(wts []Worktree) []Worktree {
	out := make([]Worktree, 0, len(wts))
	for _, w := range wts {
		if !w.IsMain {
			out = append(out, w)
		}
	}
	return out
}

func confirmMessage(targets []Worktree) string {
	var b strings.Builder
	b.WriteString("Remove the following worktrees?\n")
	for _, w := range targets {
		_, _ = fmt.Fprintf(&b, "  - %s\n", w.Path)
	}
	return b.String()
}

// List returns all worktrees with the Dirty flag populated.
func (s *Service) List(ctx context.Context) ([]Worktree, error) {
	root, err := s.git.MainRoot(ctx)
	if err != nil {
		return nil, err
	}
	wts, err := s.git.ListWorktrees(ctx, root)
	if err != nil {
		return nil, err
	}
	for i := range wts {
		dirty, err := s.git.IsDirty(ctx, wts[i].Path)
		if err != nil {
			return nil, err
		}
		wts[i].Dirty = dirty
	}
	return wts, nil
}

