package worktree

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

const configRelPath = ".worktreeinclude"

// LoadConfig reads .worktreeinclude from root. A missing file copies nothing.
func LoadConfig(root string) (Config, error) {
	path := filepath.Join(root, configRelPath)
	data, err := os.ReadFile(path) //nolint:gosec // path derived from repo root
	if errors.Is(err, fs.ErrNotExist) {
		return Config{}, nil
	}
	if err != nil {
		return Config{}, fmt.Errorf("read %s: %w", path, err)
	}
	return Config{IncludePatterns: parseIncludePatterns(data)}, nil
}

func parseIncludePatterns(data []byte) []string {
	var patterns []string
	for _, raw := range strings.Split(string(data), "\n") {
		line := strings.TrimRight(raw, "\r")
		if strings.TrimSpace(line) == "" || strings.HasPrefix(line, "#") {
			continue
		}
		patterns = append(patterns, line)
	}
	return patterns
}

