138	func appendIgnoreRule(path, rule string) error { //nolint:unparam // rule is constant today; the writer serves both ignore files
139		content, err := os.ReadFile(path) //nolint:gosec // path derived from repo root / git common dir
140		if err != nil && !errors.Is(err, os.ErrNotExist) {
141			return fmt.Errorf("failed to read %s: %w", path, err)
142		}
143		for _, line := range strings.Split(string(content), "\n") {
