152		if len(content) > 0 && !strings.HasSuffix(string(content), "\n") {
153			prefix = "\n"
154		}
155		updated := string(content) + prefix + rule + "\n"
156		if err := os.WriteFile(path, []byte(updated), 0o600); err != nil { //nolint:gosec // path derived from repo root / git common dir
157			return fmt.Errorf("failed to update %s: %w", path, err)
158		}
159		return nil
160	}
