164	// copyWorktreeIncludeFiles copies ignored files matching .worktreeinclude
165	// patterns from the main worktree root into a freshly created worktree.
166	// Per-file failures warn and skip; they never fail the checkout.
167	func copyWorktreeIncludeFiles(ctx context.Context, errW io.Writer, root, dest string) error {
168		patterns, err := loadWorktreeIncludePatterns(root)
169		if err != nil {
170			return err
171		}
172		if len(patterns) == 0 {
173			return nil
174		}
175		ignored, err := listIgnoredFiles(ctx, root)
176		if err != nil {
177			return err
178		}
179		matches := matchIncludePatterns(patterns, ignored)
180		if len(matches) == 0 {
