199	// loadWorktreeIncludePatterns reads .worktreeinclude from root. A missing
200	// file means nothing gets copied. Lines are gitignore-style patterns; blank
201	// lines and #-comments are skipped.
202	func loadWorktreeIncludePatterns(root string) ([]string, error) {
203		data, err := os.ReadFile(filepath.Join(root, worktreeIncludeFile)) //nolint:gosec // path derived from repo root
204		if errors.Is(err, fs.ErrNotExist) {
205			return nil, nil
206		}
207		if err != nil {
208			return nil, fmt.Errorf("failed to read %s: %w", worktreeIncludeFile, err)
209		}
210		var patterns []string
211		for _, raw := range strings.Split(string(data), "\n") {
212			line := strings.TrimRight(raw, "\r")
213			if strings.TrimSpace(line) == "" || strings.HasPrefix(line, "#") {
214				continue
215			}
216			patterns = append(patterns, line)
217		}
218		return patterns, nil
219	}
