239	func matchIncludePatterns(patterns, files []string) []string {
240		ps := make([]gitignore.Pattern, 0, len(patterns))
241		for _, pattern := range patterns {
242			ps = append(ps, gitignore.ParsePattern(pattern, nil))
243		}
244		matcher := gitignore.NewMatcher(ps)
245		included := make([]string, 0, len(files))
246		for _, file := range files {
247			rel, ok := cleanRelativeIncludeFile(file)
248			if !ok || isManagedTrailWorktreePath(rel) || !matcher.Match(strings.Split(filepath.ToSlash(rel), "/"), false) {
249				continue
250			}
251			included = append(included, rel)
252		}
253		return included
254	}
