318	// checkoutTrailWorktree checks branch out into a managed worktree under
319	// <main-root>/.entire/worktrees instead of switching the current checkout.
320	// The final output line is a shell-safe `cd '<path>'` hint.
321	func checkoutTrailWorktree(ctx context.Context, w, errW io.Writer, branch string, force bool, trailNumber int) error {
322		if err := ValidateBranchName(ctx, branch); err != nil {
323			return err
324		}
325	
326		existing, managed, found, err := findWorktreeForBranch(ctx, branch)
327		if err != nil {
328			return err
329		}
330		if found {
331			if !managed {
332				return fmt.Errorf("branch %q is already checked out at %s", branch, existing)
333			}
334			fmt.Fprintf(w, "Worktree already exists at %s\n", existing)
335			fmt.Fprintf(w, "cd %s\n", shellQuotePath(existing))
336			return nil
337		}
338	
339		proceed, err := ensureTrailWorktreeBranchAvailable(ctx, w, branch, force)
340		if err != nil {
341			return err
342		}
343		if !proceed {
344			fmt.Fprintf(w, "Checkout of branch %s cancelled.\n", branch)
345			return nil
346		}
347	
348		root, err := trailWorktreeBaseRoot(ctx)
349		if err != nil {
350			return fmt.Errorf("failed to find main worktree root: %w", err)
351		}
352		if err := ensureTrailWorktreeIgnoreRule(ctx, w, root, force); err != nil {
353			return err
354		}
355	
356		worktreePath := defaultTrailWorktreePath(root, branch, trailNumber)
357		if err := os.MkdirAll(filepath.Dir(worktreePath), 0o750); err != nil {
358			return fmt.Errorf("failed to create worktree parent: %w", err)
359		}
360		add := exec.CommandContext(ctx, "git", "worktree", "add", worktreePath, branch)
361		add.Dir = root
362		if output, err := add.CombinedOutput(); err != nil {
363			return fmt.Errorf("failed to create worktree: %s: %w", strings.TrimSpace(string(output)), err)
364		}
365	
366		if err := copyWorktreeIncludeFiles(ctx, errW, root, worktreePath); err != nil {
367			fmt.Fprintf(errW, "warning: could not copy %s files: %v\n", worktreeIncludeFile, err)
368		}
369	
370		fmt.Fprintf(w, "Worktree ready at %s\n", worktreePath)
371		fmt.Fprintf(w, "cd %s\n", shellQuotePath(worktreePath))
372		return nil
373	}
