375	// findWorktreeForBranch reports whether branch is already checked out in any
376	// worktree, and whether that worktree is managed under
377	// <main-root>/.entire/worktrees.
378	func findWorktreeForBranch(ctx context.Context, branch string) (path string, managed bool, found bool, err error) {
379		root, err := trailWorktreeBaseRoot(ctx)
380		if err != nil {
381			return "", false, false, fmt.Errorf("failed to find main worktree root: %w", err)
382		}
383		managedRoot := normalizeWorktreePath(filepath.Join(root, filepath.FromSlash(trailWorktreesRelDir)))
384	
385		cmd := exec.CommandContext(ctx, "git", "worktree", "list", "--porcelain")
386		output, err := cmd.Output()
387		if err != nil {
388			return "", false, false, fmt.Errorf("failed to list worktrees: %w", err)
389		}
390		var currentPath string
391		for _, line := range strings.Split(string(output), "\n") {
392			line = strings.TrimSpace(line)
393			if line == "" {
394				currentPath = ""
395				continue
396			}
397			if strings.HasPrefix(line, "worktree ") {
398				currentPath = strings.TrimSpace(strings.TrimPrefix(line, "worktree "))
399				continue
400			}
401			if strings.TrimPrefix(line, "branch ") == "refs/heads/"+branch && currentPath != "" {
402				normalized := normalizeWorktreePath(currentPath)
403				isManaged := normalized == managedRoot || strings.HasPrefix(normalized, managedRoot+string(filepath.Separator))
404				return currentPath, isManaged, true, nil
405			}
406		}
407		return "", false, false, nil
408	}
