411	// fetching it from origin when it only exists there. It returns false when
412	// the user declined the fetch prompt. --force and non-interactive runs fetch
413	// without prompting.
414	func ensureTrailWorktreeBranchAvailable(ctx context.Context, w io.Writer, branch string, force bool) (bool, error) {
415		exists, err := BranchExistsLocally(ctx, branch)
416		if err != nil {
417			return false, fmt.Errorf("failed to check branch: %w", err)
418		}
419		if exists {
420			return true, nil
421		}
422	
423		remoteExists, err := BranchExistsOnRemote(ctx, branch)
424		if err != nil {
425			return false, fmt.Errorf("failed to check remote branch: %w", err)
426		}
427		if !remoteExists {
