func TestCheckoutTrailWorktree_HealsStaleManagedWorktree(t *testing.T) {
	repoDir := newTrailWorktreeTestRepo(t)
	runGit(t, repoDir, "branch", "feature/stale")
	t.Chdir(repoDir)

	var out1, err1 bytes.Buffer
	if err := checkoutTrailWorktree(context.Background(), &out1, &err1, "feature/stale", false, 4); err != nil {
		t.Fatalf("first checkout: %v; stderr: %s", err, err1.String())
	}
	worktreePath := filepath.Join(repoDir, ".entire", "worktrees", "trail-4-feature-stale")
	if err := os.RemoveAll(worktreePath); err != nil {
		t.Fatalf("remove worktree dir: %v", err)
	}

	var out2, err2 bytes.Buffer
	if err := checkoutTrailWorktree(context.Background(), &out2, &err2, "feature/stale", false, 4); err != nil {
		t.Fatalf("second checkout: %v; stderr: %s", err, err2.String())
	}
	if !strings.Contains(out2.String(), "Worktree ready at "+worktreePath) {
		t.Fatalf("second output = %q, want recreated worktree", out2.String())
	}
	if got := currentBranchInDir(t, worktreePath); got != "feature/stale" {
		t.Fatalf("worktree branch = %q, want feature/stale", got)
	}
}

